     1→//! Helper functions and an extension trait for Ethereum 2 ENRs.
     2→
     3→pub use discv5::enr::CombinedKey;
     4→
     5→use super::ENR_FILENAME;
     6→use crate::NetworkConfig;
     7→use crate::types::{Enr, EnrAttestationBitfield, EnrSyncCommitteeBitfield};
     8→use alloy_rlp::bytes::Bytes;
     9→use libp2p::identity::Keypair;
    10→use lighthouse_version::{client_name, version};
    11→use network_utils::enr_ext::CombinedKeyExt;
    12→use network_utils::enr_ext::{EnrExt, QUIC_ENR_KEY, QUIC6_ENR_KEY};
    13→use ssz::{Decode, Encode};
    14→use ssz_types::BitVector;
    15→use std::fs::File;
    16→use std::io::prelude::*;
    17→use std::path::Path;
    18→use std::str::FromStr;
    19→use tracing::{debug, warn};
    20→use types::{ChainSpec, EnrForkId, EthSpec};
    21→
    22→/// The ENR field specifying the fork id.
    23→pub const ETH2_ENR_KEY: &str = "eth2";
    24→/// The ENR field specifying the next fork digest.
    25→pub const NEXT_FORK_DIGEST_ENR_KEY: &str = "nfd";
    26→/// The ENR field specifying the attestation subnet bitfield.
    27→pub const ATTESTATION_BITFIELD_ENR_KEY: &str = "attnets";
    28→/// The ENR field specifying the sync committee subnet bitfield.
    29→pub const SYNC_COMMITTEE_BITFIELD_ENR_KEY: &str = "syncnets";
    30→/// The ENR field specifying the peerdas custody group count.
    31→pub const PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY: &str = "cgc";
    32→
    33→/// Extension trait for ENR's within Eth2.
    34→pub trait Eth2Enr {
    35→    /// The attestation subnet bitfield associated with the ENR.
    36→    fn attestation_bitfield<E: EthSpec>(&self) -> Result<EnrAttestationBitfield<E>, &'static str>;
    37→
    38→    /// The sync committee subnet bitfield associated with the ENR.
    39→    fn sync_committee_bitfield<E: EthSpec>(
    40→        &self,
    41→    ) -> Result<EnrSyncCommitteeBitfield<E>, &'static str>;
    42→
    43→    /// The peerdas custody group count associated with the ENR.
    44→    fn custody_group_count<E: EthSpec>(&self, spec: &ChainSpec) -> Result<u64, &'static str>;
    45→
    46→    /// The next fork digest associated with the ENR.
    47→    fn next_fork_digest(&self) -> Result<[u8; 4], &'static str>;
    48→
    49→    fn eth2(&self) -> Result<EnrForkId, &'static str>;
    50→}
    51→
    52→impl Eth2Enr for Enr {
    53→    fn attestation_bitfield<E: EthSpec>(&self) -> Result<EnrAttestationBitfield<E>, &'static str> {
    54→        let bitfield_bytes: Bytes = self
    55→            .get_decodable(ATTESTATION_BITFIELD_ENR_KEY)
    56→            .ok_or("ENR attestation bitfield non-existent")?
    57→            .map_err(|_| "Invalid RLP Encoding")?;
    58→
    59→        BitVector::<E::SubnetBitfieldLength>::from_ssz_bytes(&bitfield_bytes)
    60→            .map_err(|_| "Could not decode the ENR attnets bitfield")
    61→    }
    62→
    63→    fn sync_committee_bitfield<E: EthSpec>(
    64→        &self,
    65→    ) -> Result<EnrSyncCommitteeBitfield<E>, &'static str> {
    66→        let bitfield_bytes: Bytes = self
    67→            .get_decodable(SYNC_COMMITTEE_BITFIELD_ENR_KEY)
    68→            .ok_or("ENR sync committee bitfield non-existent")?
    69→            .map_err(|_| "Invalid RLP Encoding")?;
    70→
    71→        BitVector::<E::SyncCommitteeSubnetCount>::from_ssz_bytes(&bitfield_bytes)
    72→            .map_err(|_| "Could not decode the ENR syncnets bitfield")
    73→    }
    74→
    75→    fn custody_group_count<E: EthSpec>(&self, spec: &ChainSpec) -> Result<u64, &'static str> {
    76→        let cgc = self
    77→            .get_decodable::<u64>(PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY)
    78→            .ok_or("ENR custody group count non-existent")?
    79→            .map_err(|_| "Could not decode the ENR custody group count")?;
    80→
    81→        if (spec.custody_requirement..=spec.number_of_custody_groups).contains(&cgc) {
    82→            Ok(cgc)
    83→        } else {
    84→            Err("Invalid custody group count in ENR")
    85→        }
    86→    }
    87→
    88→    fn next_fork_digest(&self) -> Result<[u8; 4], &'static str> {
    89→        self.get_decodable::<[u8; 4]>(NEXT_FORK_DIGEST_ENR_KEY)
    90→            .ok_or("ENR next fork digest non-existent")?
    91→            .map_err(|_| "Could not decode the ENR next fork digest")
    92→    }
    93→
    94→    fn eth2(&self) -> Result<EnrForkId, &'static str> {
    95→        let eth2_bytes: Bytes = self
    96→            .get_decodable(ETH2_ENR_KEY)
    97→            .ok_or("ENR has no eth2 field")?
    98→            .map_err(|_| "Invalid RLP Encoding")?;
    99→
   100→        EnrForkId::from_ssz_bytes(&eth2_bytes).map_err(|_| "Could not decode EnrForkId")
   101→    }
   102→}
   103→
   104→/// Either use the given ENR or load an ENR from file if it exists and matches the current NodeId
   105→/// and sequence number.
   106→/// If an ENR exists, with the same NodeId, this function checks to see if the loaded ENR from
   107→/// disk is suitable to use, otherwise we increment the given ENR's sequence number.
   108→pub fn use_or_load_enr(
   109→    enr_key: &CombinedKey,
   110→    local_enr: &mut Enr,
   111→    config: &NetworkConfig,
   112→) -> Result<(), String> {
   113→    let enr_f = config.network_dir.join(ENR_FILENAME);
   114→    if let Ok(mut enr_file) = File::open(enr_f.clone()) {
   115→        let mut enr_string = String::new();
   116→        match enr_file.read_to_string(&mut enr_string) {
   117→            Err(_) => debug!("Could not read ENR from file"),
   118→            Ok(_) => {
   119→                match Enr::from_str(&enr_string) {
   120→                    Ok(disk_enr) => {
   121→                        // if the same node id, then we may need to update our sequence number
   122→                        if local_enr.node_id() == disk_enr.node_id() {
   123→                            if compare_enr(local_enr, &disk_enr) {
   124→                                debug!(file = ?enr_f,"ENR loaded from disk");
   125→                                // the stored ENR has the same configuration, use it
   126→                                *local_enr = disk_enr;
   127→                                return Ok(());
   128→                            }
   129→
   130→                            // same node id, different configuration - update the sequence number
   131→                            // Note: local_enr is generated with default(0) attnets value,
   132→                            // so a non default value in persisted enr will also update sequence number.
   133→                            let new_seq_no = disk_enr.seq().checked_add(1).ok_or("ENR sequence number on file is too large. Remove it to generate a new NodeId")?;
   134→                            local_enr.set_seq(new_seq_no, enr_key).map_err(|e| {
   135→                                format!("Could not update ENR sequence number: {:?}", e)
   136→                            })?;
   137→                            debug!(seq = new_seq_no, "ENR sequence number increased");
   138→                        }
   139→                    }
   140→                    Err(e) => {
   141→                        warn!(error = ?e,"ENR from file could not be decoded");
   142→                    }
   143→                }
   144→            }
   145→        }
   146→    }
   147→
   148→    save_enr_to_disk(&config.network_dir, local_enr);
   149→
   150→    Ok(())
   151→}
   152→
   153→/// Loads an ENR from file if it exists and matches the current NodeId and sequence number. If none
   154→/// exists, generates a new one.
   155→///
   156→/// If an ENR exists, with the same NodeId, this function checks to see if the loaded ENR from
   157→/// disk is suitable to use, otherwise we increment our newly generated ENR's sequence number.
   158→pub fn build_or_load_enr<E: EthSpec>(
   159→    local_key: Keypair,
   160→    config: &NetworkConfig,
   161→    enr_fork_id: &EnrForkId,
   162→    custody_group_count: Option<u64>,
   163→    next_fork_digest: [u8; 4],
   164→    spec: &ChainSpec,
   165→) -> Result<Enr, String> {
   166→    // Build the local ENR.
   167→    // Note: Discovery should update the ENR record's IP to the external IP as seen by the
   168→    // majority of our peers, if the CLI doesn't expressly forbid it.
   169→    let enr_key = CombinedKey::from_libp2p(local_key)?;
   170→    let mut local_enr = build_enr::<E>(
   171→        &enr_key,
   172→        config,
   173→        enr_fork_id,
   174→        custody_group_count,
   175→        next_fork_digest,
   176→        spec,
   177→    )?;
   178→
   179→    use_or_load_enr(&enr_key, &mut local_enr, config)?;
   180→    Ok(local_enr)
   181→}
   182→
   183→/// Builds a lighthouse ENR given a `NetworkConfig`.
   184→pub fn build_enr<E: EthSpec>(
   185→    enr_key: &CombinedKey,
   186→    config: &NetworkConfig,
   187→    enr_fork_id: &EnrForkId,
   188→    custody_group_count: Option<u64>,
   189→    next_fork_digest: [u8; 4],
   190→    spec: &ChainSpec,
   191→) -> Result<Enr, String> {
   192→    let mut builder = discv5::enr::Enr::builder();
   193→    let (maybe_ipv4_address, maybe_ipv6_address) = &config.enr_address;
   194→
   195→    if let Some(ip) = maybe_ipv4_address {
   196→        builder.ip4(*ip);
   197→    }
   198→
   199→    if let Some(ip) = maybe_ipv6_address {
   200→        builder.ip6(*ip);
   201→    }
   202→
   203→    if let Some(udp4_port) = config.enr_udp4_port {
   204→        builder.udp4(udp4_port.get());
   205→    }
   206→
   207→    if let Some(udp6_port) = config.enr_udp6_port {
   208→        builder.udp6(udp6_port.get());
   209→    }
   210→
   211→    // Add EIP 7636 client information
   212→    if !config.private {
   213→        builder.client_info(client_name().to_string(), version().to_string(), None);
   214→    }
   215→
   216→    // Add QUIC fields to the ENR.
   217→    // Since QUIC is used as an alternative transport for the libp2p protocols,
   218→    // the related fields should only be added when both QUIC and libp2p are enabled
   219→    if !config.disable_quic_support {
   220→        // If we are listening on ipv4, add the quic ipv4 port.
   221→        if let Some(quic4_port) = config.enr_quic4_port.or_else(|| {
   222→            config
   223→                .listen_addrs()
   224→                .v4()
   225→                .and_then(|v4_addr| v4_addr.quic_port.try_into().ok())
   226→        }) {
   227→            builder.add_value(QUIC_ENR_KEY, &quic4_port.get());
   228→        }
   229→
   230→        // If we are listening on ipv6, add the quic ipv6 port.
   231→        if let Some(quic6_port) = config.enr_quic6_port.or_else(|| {
   232→            config
   233→                .listen_addrs()
   234→                .v6()
   235→                .and_then(|v6_addr| v6_addr.quic_port.try_into().ok())
   236→        }) {
   237→            builder.add_value(QUIC6_ENR_KEY, &quic6_port.get());
   238→        }
   239→    }
   240→
   241→    // If the ENR port is not set, and we are listening over that ip version, use the listening port instead.
   242→    let tcp4_port = config.enr_tcp4_port.or_else(|| {
   243→        config
   244→            .listen_addrs()
   245→            .v4()
   246→            .and_then(|v4_addr| v4_addr.tcp_port.try_into().ok())
   247→    });
   248→    if let Some(tcp4_port) = tcp4_port {
   249→        builder.tcp4(tcp4_port.get());
   250→    }
   251→
   252→    let tcp6_port = config.enr_tcp6_port.or_else(|| {
   253→        config
   254→            .listen_addrs()
   255→            .v6()
   256→            .and_then(|v6_addr| v6_addr.tcp_port.try_into().ok())
   257→    });
   258→    if let Some(tcp6_port) = tcp6_port {
   259→        builder.tcp6(tcp6_port.get());
   260→    }
   261→
   262→    // set the `eth2` field on our ENR
   263→    builder.add_value::<Bytes>(ETH2_ENR_KEY, &enr_fork_id.as_ssz_bytes().into());
   264→
   265→    // set the "attnets" field on our ENR
   266→    let bitfield = BitVector::<E::SubnetBitfieldLength>::new();
   267→
   268→    builder.add_value::<Bytes>(
   269→        ATTESTATION_BITFIELD_ENR_KEY,
   270→        &bitfield.as_ssz_bytes().into(),
   271→    );
   272→
   273→    // set the "syncnets" field on our ENR
   274→    let bitfield = BitVector::<E::SyncCommitteeSubnetCount>::new();
   275→
   276→    builder.add_value::<Bytes>(
   277→        SYNC_COMMITTEE_BITFIELD_ENR_KEY,
   278→        &bitfield.as_ssz_bytes().into(),
   279→    );
   280→
   281→    // only set `cgc` and `nfd` if PeerDAS fork (Fulu) epoch has been scheduled
   282→    if spec.is_peer_das_scheduled() {
   283→        let custody_group_count = if let Some(cgc) = custody_group_count {
   284→            cgc
   285→        } else if let Some(false_cgc) = config.advertise_false_custody_group_count {
   286→            false_cgc
   287→        } else if config.subscribe_all_data_column_subnets {
   288→            spec.number_of_custody_groups
   289→        } else {
   290→            spec.custody_requirement
   291→        };
   292→        builder.add_value(PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY, &custody_group_count);
   293→        builder.add_value(NEXT_FORK_DIGEST_ENR_KEY, &next_fork_digest);
   294→    }
   295→
   296→    builder
   297→        .build(enr_key)
   298→        .map_err(|e| format!("Could not build Local ENR: {:?}", e))
   299→}
   300→
   301→/// Defines the conditions under which we use the locally built ENR or the one stored on disk.
   302→/// If this function returns true, we use the `disk_enr`.
   303→fn compare_enr(local_enr: &Enr, disk_enr: &Enr) -> bool {
   304→    // take preference over disk_enr address if one is not specified
   305→    (local_enr.ip4().is_none() || local_enr.ip4() == disk_enr.ip4())
   306→        &&
   307→    (local_enr.ip6().is_none() || local_enr.ip6() == disk_enr.ip6())
   308→        // tcp ports must match
   309→        && local_enr.tcp4() == disk_enr.tcp4()
   310→        && local_enr.tcp6() == disk_enr.tcp6()
   311→        // quic ports must match
   312→        && local_enr.quic4() == disk_enr.quic4()
   313→        && local_enr.quic6() == disk_enr.quic6()
   314→        // must match on the same fork
   315→        && local_enr.get_decodable::<Bytes>(ETH2_ENR_KEY) == disk_enr.get_decodable(ETH2_ENR_KEY)
   316→        // take preference over disk udp port if one is not specified
   317→        && (local_enr.udp4().is_none() || local_enr.udp4() == disk_enr.udp4())
   318→        && (local_enr.udp6().is_none() || local_enr.udp6() == disk_enr.udp6())
   319→        // we need the ATTESTATION_BITFIELD_ENR_KEY and SYNC_COMMITTEE_BITFIELD_ENR_KEY and
   320→        // PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY key to match, otherwise we use a new ENR. This will
   321→        // likely only be true for non-validating nodes.
   322→        && local_enr.get_decodable::<Bytes>(ATTESTATION_BITFIELD_ENR_KEY) == disk_enr.get_decodable(ATTESTATION_BITFIELD_ENR_KEY)
   323→        && local_enr.get_decodable::<Bytes>(SYNC_COMMITTEE_BITFIELD_ENR_KEY) == disk_enr.get_decodable(SYNC_COMMITTEE_BITFIELD_ENR_KEY)
   324→        && local_enr.get_decodable::<Bytes>(PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY) == disk_enr.get_decodable(PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY)
   325→}
   326→
   327→/// Loads enr from the given directory
   328→pub fn load_enr_from_disk(dir: &Path) -> Result<Enr, String> {
   329→    let enr_f = dir.join(ENR_FILENAME);
   330→    let mut enr_file =
   331→        File::open(enr_f).map_err(|e| format!("Failed to open enr file: {:?}", e))?;
   332→    let mut enr_string = String::new();
   333→    match enr_file.read_to_string(&mut enr_string) {
   334→        Err(_) => Err("Could not read ENR from file".to_string()),
   335→        Ok(_) => Enr::from_str(&enr_string)
   336→            .map_err(|e| format!("ENR from file could not be decoded: {:?}", e)),
   337→    }
   338→}
   339→
   340→/// Saves an ENR to disk
   341→pub fn save_enr_to_disk(dir: &Path, enr: &Enr) {
   342→    let _ = std::fs::create_dir_all(dir);
   343→    match File::create(dir.join(Path::new(ENR_FILENAME)))
   344→        .and_then(|mut f| f.write_all(enr.to_base64().as_bytes()))
   345→    {
   346→        Ok(_) => {
   347→            debug!("ENR written to disk");
   348→        }
   349→        Err(e) => {
   350→            warn!(
   351→                file = format!("{:?}{:?}",dir, ENR_FILENAME),
   352→                error = %e,
   353→                "Could not write ENR to file"
   354→            );
   355→        }
   356→    }
   357→}
